public Book Snapshot()
{
    Book copy = new Book();
    foreach (KeyValuePair<string, Order> entry in orders)
    {
        copy.orders.Add(entry.Key, CopyOf(entry.Value));
    }
    return copy;
}

// Lines and amounts are immutable, so the copy shares them; the order itself is rebuilt
// and moved to the same status.
private static Order CopyOf(Order order)
{
    Order copy = new Order(order.Id);
    foreach (OrderLine line in order.Lines)
    {
        copy.Add(line);
    }
    copy.Note = order.Note;
    switch (order.Status)
    {
        case OrderStatus.Paid:
            copy.Pay();
            break;
        case OrderStatus.Shipped:
            copy.Pay();
            copy.Ship();
            break;
        case OrderStatus.Cancelled:
            copy.Cancel();
            break;
    }
    return copy;
}

